"""Migrated Meridian CRM 4.2 opportunity_pipeline workflow."""

from decimal import Decimal


def _field(record: dict, name: str):
    """Return a legacy field value, with missing fields represented as empty."""
    return record.get(name, "")


def _numeric(value) -> Decimal:
    """Apply the relevant VRL numeric coercion: empty values compare as zero."""
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one opportunity_pipeline workflow event."""
    result_record = dict(record)

    transitions = (
        ("P", "Q", "qualify", lambda r: _numeric(_field(r, "AMT")) > 0,
         (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
        ("Q", "N", "advance", None,
         (("set", "STAGE_PCT", "60"),)),
        ("N", "W", "close_won",
         lambda r: _field(r, "CLOSE_DT") != "00000000",
         (("set", "STAGE_PCT", "100"), ("audit", "OPP_WON"),
          ("notify", "won_deal"))),
        ("P", "L", "close_lost",
         lambda r: _field(r, "LOST_RSN") != "",
         (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("Q", "L", "close_lost",
         lambda r: _field(r, "LOST_RSN") != "",
         (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("N", "L", "close_lost",
         lambda r: _field(r, "LOST_RSN") != "",
         (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
    )

    for from_state, to_state, transition_event, guard, actions in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        audits = []
        notifies = []
        for action in actions:
            if action[0] == "set":
                result_record[action[1]] = action[2]
            elif action[0] == "audit":
                audits.append(action[1])
            else:
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
